import unreal,json
from pathlib import Path
root=Path(unreal.Paths.project_dir()).parents[1]
exec((root/'work/migrate_delivery_blueprints.py').read_text(encoding='utf-8-sig').split('reports=[]')[0])
bp=unreal.load_asset('/Game/Delivery/Vehicles/BP_DeliveryRider');reports=[]
g=Graph();g.get('Sprint');g.call('Speed','SelectFloat',M,A='650',B='390');g.link('Sprint','Sprint','Speed','bPickA');g.link('Speed','ReturnValue','result','ReturnValue');g.exec('entry','result');reports.append(g.build('WalkingSpeed'))
g=Graph();g.get('BikeSpeed');g.get('ForwardInput')
g.call('Target','Multiply_DoubleDouble',M);g.link('ForwardInput','ForwardInput','Target','A');g.link('entry','TopSpeed','Target','B')
g.call('Coasting','EqualEqual_DoubleDouble',M,B='0');g.link('ForwardInput','ForwardInput','Coasting','A')
g.call('Acceleration','SelectFloat',M,A='350',B='600');g.link('Coasting','ReturnValue','Acceleration','bPickA')
g.call('Speed','FInterpTo_Constant',M);g.link('BikeSpeed','BikeSpeed','Speed','Current');g.link('Target','ReturnValue','Speed','Target');g.link('entry','Dt','Speed','DeltaTime');g.link('Acceleration','ReturnValue','Speed','InterpSpeed');g.link('Speed','ReturnValue','result','ReturnValue');g.exec('entry','result');reports.append(g.build('AdvanceDriveSpeed'))
g=Graph();g.get('BikeSpeed');g.get('SideInput')
g.call('Magnitude','Abs',M);g.link('BikeSpeed','BikeSpeed','Magnitude','A')
g.call('Ratio','Divide_DoubleDouble',M,B='200');g.link('Magnitude','ReturnValue','Ratio','A')
g.call('Clamp','FClamp',M,Min='0',Max='1');g.link('Ratio','ReturnValue','Clamp','Value')
g.call('Rate','Multiply_DoubleDouble',M,B='75');g.link('Clamp','ReturnValue','Rate','A')
g.call('InputRate','Multiply_DoubleDouble',M);g.link('Rate','ReturnValue','InputRate','A');g.link('SideInput','SideInput','InputRate','B')
g.call('Angle','Multiply_DoubleDouble',M);g.link('InputRate','ReturnValue','Angle','A');g.link('entry','Dt','Angle','B')
g.call('Reverse','Less_DoubleDouble',M,B='0');g.link('BikeSpeed','BikeSpeed','Reverse','A')
g.call('Sign','SelectFloat',M,A='-1',B='1');g.link('Reverse','ReturnValue','Sign','bPickA')
g.call('SignedAngle','Multiply_DoubleDouble',M);g.link('Angle','ReturnValue','SignedAngle','A');g.link('Sign','ReturnValue','SignedAngle','B');g.link('SignedAngle','ReturnValue','result','ReturnValue');g.exec('entry','result');reports.append(g.build('SteeringAngle'))

g=Graph()
for v in ['CameraBoom','Camera','Delivery','Riding']:g.get(v)
g.node('Store','getfield',owner='/Script/BogotaVoxel.DeliveryComponent',var='InsideStore');g.link('Delivery','Delivery','Store','self')
g.call('Interior','IsValid','/Script/Engine.KismetSystemLibrary');g.link('Store','InsideStore','Interior','Object')
g.call('OutdoorArm','SelectFloat',M,A='530',B='430');g.link('Riding','Riding','OutdoorArm','bPickA')
g.call('TargetArm','SelectFloat',M,A='240');g.link('OutdoorArm','ReturnValue','TargetArm','B');g.link('Interior','ReturnValue','TargetArm','bPickA')
g.node('CurrentArm','getfield',owner='/Script/Engine.SpringArmComponent',var='TargetArmLength');g.link('CameraBoom','CameraBoom','CurrentArm','self')
g.call('SmoothArm','FInterpTo',M,InterpSpeed='3');g.link('CurrentArm','TargetArmLength','SmoothArm','Current');g.link('TargetArm','ReturnValue','SmoothArm','Target');g.link('entry','Dt','SmoothArm','DeltaTime')
g.node('SetArm','setfield',owner='/Script/Engine.SpringArmComponent',var='TargetArmLength');g.link('CameraBoom','CameraBoom','SetArm','self');g.link('SmoothArm','ReturnValue','SetArm','TargetArmLength')
g.call('UseLag','Not_PreBool',M);g.link('Interior','ReturnValue','UseLag','A')
g.node('SetLag','setfield',owner='/Script/Engine.SpringArmComponent',var='bEnableCameraLag');g.link('CameraBoom','CameraBoom','SetLag','self');g.link('UseLag','ReturnValue','SetLag','bEnableCameraLag')
g.call('Shoulder','SelectFloat',M,A='0',B='45');g.link('Interior','ReturnValue','Shoulder','bPickA')
g.call('Offset','MakeVector',M,X='0',Z='70');g.link('Shoulder','ReturnValue','Offset','Y')
g.node('SetOffset','setfield',owner='/Script/Engine.SpringArmComponent',var='SocketOffset');g.link('CameraBoom','CameraBoom','SetOffset','self');g.link('Offset','ReturnValue','SetOffset','SocketOffset')
g.call('ViewAngle','SelectFloat',M,A='78',B='75');g.link('Interior','ReturnValue','ViewAngle','bPickA')
g.call('SetFOV','SetFieldOfView','/Script/Engine.CameraComponent');g.link('Camera','Camera','SetFOV','self');g.link('ViewAngle','ReturnValue','SetFOV','InFieldOfView')
chain=['entry','SetArm','SetLag','SetOffset','SetFOV','result']
for a,b in zip(chain,chain[1:]):g.exec(a,b)
reports.append(g.build('UpdateCameraRig'))
assert unreal.EditorAssetLibrary.save_loaded_asset(bp,only_if_is_dirty=False)
p=Path(unreal.Paths.project_saved_dir(),'blueprint_migration.json');data=json.loads(p.read_text());data['player_drive_camera_graphs']=reports;p.write_text(json.dumps(data,indent=2))
unreal.log('PLAYER_DRIVE_CAMERA_BLUEPRINTS_SAVED '+json.dumps(reports))
